        g = r;
        b = r;
        if (emon.Port.BitmapChannels(src) >= 3) {
            g = emon.Port.CellsAt(mask, n + 134) / ink;
            b = emon.Port.CellsAt(mask, n + 135) / ink;
        }
        rgb = ((r * 65536) + (g * 256)) + b;
        return SpAdd(cand, kind, row, x0, y0, x1, y1, ink, rgb, swc, conf);
    }
    internal static int SpZone(int page1, emon.Port.Cells views, int srcview, emon.Port.Cells owords, emon.Port.Cells etext, emon.Port.Bitmap src, emon.Port.Cells rules, int r, int skipfirst, int skipcount, emon.Port.Cells cand, emon.Port.Cells mask) {
        // Measure the zone of rules row r and, when its ink is a pen's, append a candidate to `cand` (see the head of this file). `mask` is the zone's ink map (one cell a pixel) and the
        // statistics after it. Answers 1 when a candidate was added.
        int rx0 = Evidence.RlGet(rules, r, Evidence.RlfX0()) - SpSide();
        int rx1 = Evidence.RlGet(rules, r, Evidence.RlfX1()) + SpSide();
        int ry = (Evidence.RlGet(rules, r, Evidence.RlfY0()) + Evidence.RlGet(rules, r, Evidence.RlfY1())) / 2;
        int th = Evidence.RlGet(rules, r, Evidence.RlfY1()) - Evidence.RlGet(rules, r, Evidence.RlfY0());
        int rpy = Evidence.VwCptToPx(views, srcview, 1, rx0, ry);
        int zx0 = Evidence.VwCptToPx(views, srcview, 0, rx0, ry - SpUp());
        int zy0 = Evidence.VwCptToPx(views, srcview, 1, rx0, ry - SpUp());
        int zx1 = Evidence.VwCptToPx(views, srcview, 0, rx1, ry + SpDown());
        int zy1 = Evidence.VwCptToPx(views, srcview, 1, rx1, ry + SpDown());
        int zw = 0;
        int zh = 0;
        int band = 2;
        int ink = 0;
        int k = 0;
        if (zx0 < 0) {
            zx0 = 0;
        }
        if (zy0 < 0) {
            zy0 = 0;
        }
        if (zx1 > emon.Port.BitmapW(src)) {
            zx1 = emon.Port.BitmapW(src);
        }
        if (zy1 > emon.Port.BitmapH(src)) {
            zy1 = emon.Port.BitmapH(src);
        }
        zw = zx1 - zx0;
        zh = zy1 - zy0;
        if ((zw <= 8) || (zh <= 8)) {
            return 0;
        }
        if ((zw * zh) > SpMaxZone()) {
            return 0;
        }
        band = 2 + (((th + 100) * zh) / (2 * (SpUp() + SpDown())));
        emon.Port.CellsDrop(mask, 0);
        while (k < (zw * zh)) {
            emon.Port.CellsPush(mask, 0);
            k += 1;
        }
        ink = SpMap(src, zx0, zy0, zw, zh, rpy, band, mask);
        if (ink < SpMinInk()) {
            return 0;
        }
        SpMaskWords(page1, owords, etext, views, srcview, zx0, zy0, zw, zh, skipfirst, skipcount, mask);
        ink = SpStats(src, zx0, zy0, zw, zh, mask, zw * zh);
        if (ink < SpMinInk()) {
            return 0;
        }
        return SpJudge(page1, views, srcview, owords, etext, src, rules, r, zx0, zy0, mask, zw * zh, zw, zh, cand);
    }
    public static int SpFindWithout(int page1, emon.Port.Cells views, int srcview, emon.Port.Cells rules, emon.Port.Cells owords, emon.Port.Cells etext, emon.Port.Bitmap src, int pw, int skipfirst, int skipcount, emon.Port.Cells cand, emon.Port.Cells mask) {
        // The candidates of page `page1` (1-based) from the tracer's rules of the raster `srcview` (a `views` row; `src` its pixels): see the head of this file; written to `cand` (cleared
        // first). `mask` is scratch. Answers how many.
        int n = Evidence.RlCount(rules);
        int r = 0;
        int looked = 0;
        emon.Port.CellsDrop(cand, 0);
        while (r < n) {
            if (Evidence.RlGet(rules, r, Evidence.RlfPage()) == page1) {
                if ((looked < SpMax()) && ((SpIsRule(rules, r, pw) == 1) && (SpFramed(page1, rules, r, pw) == 0))) {
                    looked += 1;
                    SpZone(page1, views, srcview, owords, etext, src, rules, r, skipfirst, skipcount, cand, mask);
                }
            }
            r += 1;
        }
        return emon.Port.CellsLen(cand) / SpW();
    }
    public static int SpFind(int page1, emon.Port.Cells views, int srcview, emon.Port.Cells rules, emon.Port.Cells owords, emon.Port.Cells etext, emon.Port.Bitmap src, int pw, emon.Port.Cells cand, emon.Port.Cells mask) {
        return SpFindWithout(page1, views, srcview, rules, owords, etext, src, pw, 0, 0, cand, mask);
    }
    public static int SpRecord(int page0, emon.Port.Cells cand, emon.Port.Cells cg) {
        // One correspondence group a candidate: no word, its box the ink's, its colour code (`sm-hue`) in `rot`, flagged `in-seal`, `seal-px` and `seal-sig` or `seal-init`. Answers the groups written.
        int n = emon.Port.CellsLen(cand) / SpW();
        int j = 0;
        int c = 0;
        int g = 0;
        int fl = 0;
        while (j < n) {
            c = j * SpW();
            g = Player.CgNew(cg, page0 + 1, emon.Port.CellsAt(cand, c + 2), emon.Port.CellsAt(cand, c + 3), emon.Port.CellsAt(cand, c + 4), emon.Port.CellsAt(cand, c + 5), Sealmark.SmHue(emon.Port.CellsAt(cand, c + 7)));
            fl = Player.PlgInSeal() + Player.PlgSealPx();
            if (emon.Port.CellsAt(cand, c) == 3) {
                fl += Player.PlgSealSig();
            } else {
                fl += Player.PlgSealInit();
            }
            Player.CgSet(cg, g, Player.CgfFlags(), fl);
            j += 1;
        }
        return n;
    }
    public static int SpDropLines(emon.Port.Cells scr, int nsel, emon.Port.Cells olines, emon.Port.Cells owords, emon.Port.Cells cand) {
        // A scanned page's chosen lines (the selection of `scr`) without the lines that the strokes of a candidate made: every word of the line has its centre in a candidate's box and the engine
        // was under 600 per mille sure of them on average (a typed name the strokes are drawn over is read with confidence and stays), or at least 60 per cent of them do and it was under 450.
        // Answers the lines left.
        int n = emon.Port.CellsLen(cand) / SpW();
        int k = 0;
        int @out = 0;
        int l = 0;
        int f = 0;
        int cnt = 0;
        int j = 0;
        int q = 0;
        int nin = 0;
        int csum = 0;
        int inone = 0;
        int wi = 0;
        int gone = 0;
        int cx = 0;
        int cy = 0;
        while (k < nsel) {
            l = emon.Port.CellsAt(scr, Scan.ScSelBase() + k);
            f = Evidence.OlGet(olines, l, Evidence.LhFirst());
            cnt = Evidence.OlGet(olines, l, Evidence.LhCount());
            nin = 0;
            csum = 0;
            gone = 0;
            if (cnt > 0) {
                j = 0;
                while (j < cnt) {
                    wi = f + j;
                    cx = (Evidence.OwGet(owords, wi, Evidence.HdX0()) + Evidence.OwGet(owords, wi, Evidence.HdX1())) / 2;
                    cy = (Evidence.OwGet(owords, wi, Evidence.HdY0()) + Evidence.OwGet(owords, wi, Evidence.HdY1())) / 2;
                    inone = 0;
                    q = 0;
                    while (q < n) {
                        if ((cx >= emon.Port.CellsAt(cand, (q * SpW()) + 2)) && ((cx <= emon.Port.CellsAt(cand, (q * SpW()) + 4)) && ((cy >= emon.Port.CellsAt(cand, (q * SpW()) + 3)) && (cy <= emon.Port.CellsAt(cand, (q * SpW()) + 5))))) {
                            inone = 1;
                        }
                        q += 1;
                    }
                    if (inone == 1) {
                        nin += 1;
                    }
                    csum += Evidence.OwGet(owords, wi, Evidence.HdConf());
                    j += 1;
                }
                if ((nin == cnt) && (csum < (cnt * 600))) {
                    gone = 1;
                }
                if (((nin * 100) >= (cnt * 60)) && (csum < (cnt * 450))) {
                    gone = 1;
                }
            }
            if (gone == 0) {
                emon.Port.CellsSet(scr, Scan.ScSelBase() + @out, l);
                @out += 1;
            }
            k += 1;
        }
        return @out;
    }
}
